// Retratos dibujados de los cuatro protagonistas para los cuadros de diálogo, con sus emociones
// (normal, contento, triste y enfadado). Sustituyen a los retratos generados.
(function () {
  'use strict';
  const TH = window.TH;
  const SRC = {"kaelen": {"neutral": "data:image/png;base64,", "happy": "data:image/png;base64,", "sad": "data:image/png;base64,", "angry": "data:image/png;base64,"}, "elara": {"neutral": "data:image/png;base64,", "happy": "data:image/png;base64,", "sad": "data:image/png;base64,", "angry": "data:image/png;base64,"}, "flint": {"neutral": "data:image/png;base64,", "happy": "data:image/png;base64,", "sad": "data:image/png;base64,", "angry": "data:image/png;base64,"}, "firion": {"neutral": "data:image/png;base64,", "happy": "data:image/png;base64,", "sad": "data:image/png;base64,", "angry": "data:image/png;base64,"}};
  const CV = {};
  for (const id in SRC) {
    CV[id] = {};
    for (const e in SRC[id]) {
      const o = TH.makeCanvas(64, 64), im = new Image();
      im.onload = () => o.g.drawImage(im, 0, 0);
      im.src = SRC[id][e];
      CV[id][e] = o.c;
    }
  }
  const P = TH.portraits, _get = P.get.bind(P);
  P.get = function (id, expr) {
    const set = CV[id];
    if (!set) return _get(id, expr);
    return set[expr] || set.neutral;
  };
})();
